import django.db.models.deletion
from django.db import migrations, models


APPROVAL_NODE_KEYS = ('early-approval', 'late-approval')
DEFAULT_STEPS = (
    ('组长审批', '组长-陈明'),
    ('区域经理审批', '区域经理-周宁'),
)


def backfill_presales_approvals(apps, _schema_editor):
    Node = apps.get_model('after_sales_api', 'ProjectNode')
    Step = apps.get_model('after_sales_api', 'PresalesApprovalStep')
    Revision = apps.get_model('after_sales_api', 'PresalesApprovalRevision')
    audit = {
        'created_by': 'system-migration',
        'created_actor_id': 'system-migration',
        'updated_by': 'system-migration',
        'updated_actor_id': 'system-migration',
    }

    nodes = Node.objects.filter(
        project__service_type='presales',
        node_key__in=APPROVAL_NODE_KEYS,
    )
    for node in nodes.iterator():
        data = node.business_data if isinstance(node.business_data, dict) else {}
        outcome = str(data.get('outcome') or '').strip()
        decision_time = node.completed_at or node.updated_at
        approval_steps = []
        for sequence, (title, approver_name) in enumerate(DEFAULT_STEPS, start=1):
            if outcome == 'approved':
                status = 'approved'
                opinion = '历史审批数据由节点立项成功结果回填。'
            elif outcome == 'denied' and sequence == 1:
                status = 'rejected'
                opinion = '历史审批数据由节点立项否决结果回填。'
            else:
                status = 'pending'
                opinion = ''
            step = Step.objects.create(
                node_id=node.id,
                sequence=sequence,
                title=title,
                approver_name=approver_name,
                status=status,
                opinion=opinion,
                decided_at=decision_time if status != 'pending' else None,
                **audit,
            )
            revision = Revision.objects.create(
                step_id=step.id,
                revision=1,
                title=title,
                approver_name=approver_name,
                status=status,
                opinion=opinion,
                decided_at=decision_time if status != 'pending' else None,
                recorded_by_user_id='system-migration',
                recorded_by_name='系统迁移',
                recorded_actor_id='system-migration',
            )
            if decision_time:
                Revision.objects.filter(pk=revision.pk).update(recorded_at=decision_time)
            approval_steps.append({
                'id': step.id,
                'sequence': sequence,
                'title': title,
                'approverUserId': '',
                'approverName': approver_name,
                'status': status,
                'opinion': opinion,
                'decidedAt': decision_time.isoformat() if status != 'pending' and decision_time else None,
            })
        Node.objects.filter(pk=node.pk).update(
            business_data={**data, 'approvalSteps': approval_steps},
        )


def remove_presales_approval_snapshots(apps, _schema_editor):
    Node = apps.get_model('after_sales_api', 'ProjectNode')
    nodes = Node.objects.filter(
        project__service_type='presales',
        node_key__in=APPROVAL_NODE_KEYS,
    )
    for node in nodes.iterator():
        data = dict(node.business_data) if isinstance(node.business_data, dict) else {}
        data.pop('approvalSteps', None)
        Node.objects.filter(pk=node.pk).update(business_data=data)


